#!/bin/bash
# goAmnezia pro — словарь EN, модуль lib/upstream.sh (обновления из официального репозитория Amnezia)
# shellcheck disable=SC2034,SC2148

I18N[upstream_err_unreachable]="GitHub and Docker Hub are unreachable from this server — check DNS and internet access (or a proxy) and retry later; the menu and profiles keep working"
I18N[upstream_warn_github_unreachable]="GitHub is unreachable — the release tag and scripts were not checked, comparing Docker Hub images only"
I18N[upstream_warn_hub_unreachable]="Docker Hub is unreachable — images were not checked, comparing scripts against the GitHub release only"
I18N[upstream_warn_unsupported]="Release %s introduces parameters unknown to the goAmnezia generator: %s — they are not supported and not substituted; support comes with a goAmnezia release"
I18N[upstream_hint_update]="An update is available. It is applied only on demand: upstream-update --profile=<profile> (with backup, verification and rollback on failure)"
I18N[upstream_hint_current]="Everything is current: images and scripts match the official ones"
I18N[upstream_hint_client_only]="No updates for the server: profile images and scripts are current. Amnezia app %s is out — users should update the app"
I18N[upstream_err_backup_why]="The backup before the update failed — update cancelled, nothing changed. Reason: %s"
I18N[upstream_core_keeps_newer]="Profile %s already runs image %s — newer than the one pinned by the release (%s): repairing on it, no rollback. To change the image use «Amnezia updates»"
I18N[upstream_hint_scripts_unreachable]="The profile images are current. Client release %s is out, but its scripts could not be downloaded from this server (GitHub unreachable) — there is no way to tell whether anything changed for the server. Check again later."
I18N[upstream_step_backup]="Backup before the core update…"
I18N[upstream_err_backup]="The backup before the update failed — update cancelled, nothing changed"
I18N[upstream_warn_no_backup]="lib/backup.sh is not loaded — updating without a backup"
I18N[upstream_err_tag_not_found]="Tag %s was not found on Docker Hub for image %s"
I18N[upstream_err_already_current]="Profile %s already runs the current image %s and the scripts match the release — nothing to update"
I18N[upstream_updating]="Updating the core of profile %s: %s → %s"
I18N[upstream_step_scripts]="Release %s scripts: saving the previous ones, downloading new, comparing placeholders…"
I18N[upstream_err_download]="Failed to download the server scripts of release %s — update cancelled"
I18N[upstream_err_scripts_write]="Failed to write scripts into %s — previous ones restored"
I18N[upstream_warn_warp]="The container of profile %s has goWARP PRO WARP: its lines are carried into the new start.sh, /opt/warp and /opt/warp-tools come back from the state copy"
I18N[upstream_step_pull]="Pulling image %s…"
I18N[upstream_step_core]="Recreating the container from the state copy (keys unchanged)…"
I18N[upstream_update_failed_rolled_back]="The update of profile %s failed verification — image and scripts rolled back"
I18N[upstream_update_failed_dirty]="The update of profile %s failed verification and the previous image could NOT be restored. Container %s is down: bring it up with core-update or restore the installation from a backup (backup-restore)"
I18N[upstream_warn_tag_unsafe]="The release tag from the service is not usable in a path or a URL (%s) — scripts are not downloaded for it, only the image is updated"
I18N[upstream_warn_images_json]="Failed to update %s — new profile installs will use the previous image"
I18N[upstream_updated]="Core of profile %s updated to %s; the previous image is kept for rollback (upstream-rollback)"
I18N[upstream_err_no_previous]="Profile %s has no saved previous image — nothing to roll back to"
I18N[upstream_rolling_back]="Rolling profile %s back: %s → %s"
I18N[upstream_err_rollback]="Rollback of profile %s failed — restore from a backup (backup-restore)"
I18N[upstream_err_rollback_restored]="The rollback of profile %s failed; the profile was brought back up from the state copy — keys are unchanged. You can retry the rollback later"
I18N[upstream_err_rollback_down]="The rollback of profile %s failed and container %s is not up now. Recreate it from the saved state: «Protocols → profile card → Recreate the container» — keys are kept"
I18N[upstream_rolled_back]="Profile %s rolled back to image %s"
I18N[upstream_err_core]="Recreating the container of profile %s failed — check docker and state/"
I18N[upstream_core_done]="Container of profile %s recreated on the pinned image %s, keys unchanged"
I18N[upstream_tick_unreachable]="Amnezia update check: sources unreachable, will retry tomorrow"
I18N[upstream_tick_notified]="An Amnezia update is available — notification sent to the bot"
I18N[upstream_tick_current]="Amnezia update check: everything is current"
